def maxNumber(nums1: list[int], nums2: list[int], k: int) -> list[int]:
    def max_sub(nums, length):
        stack = []
        drop = len(nums) - length
        for num in nums:
            while drop and stack and stack[-1] < num:
                stack.pop()
                drop -= 1
            stack.append(num)
        return stack[:length]
    def merge(s1, s2):
        res = []
        i = j = 0
        while i < len(s1) or j < len(s2):
            if s1[i:] > s2[j:]:
                res.append(s1[i])
                i += 1
            else:
                res.append(s2[j])
                j += 1
        return res
    best = []
    for len1 in range(max(0, k - len(nums2)), min(k, len(nums1)) + 1):
        len2 = k - len1
        s1 = max_sub(nums1, len1)
        s2 = max_sub(nums2, len2)
        cand = merge(s1, s2)
        if cand > best:
            best = cand
    return best

